//! Console read models: the rows each of the six release consoles shows, as the
//! TypeScript contract in `sdk/ts/src` defines them. Generated by
//! `clients/demo/tools/gen-read-models.mjs`; `decode`, `motion` (no TypeScript
//! counterpart) and this module's type registry are written by hand.
//! `[FR-C-1]` `[AC-C-13]`

use attest::json::Json;

pub mod decode;

pub mod admin;
pub mod bifrost;
pub mod common;
pub mod forge;
pub mod heimdall;
pub mod midgard;
pub mod mimir;
pub mod motion;

use decode::{DecodeError, FromJson};

macro_rules! registry {
    ($($module:ident :: $ty:ident),* $(,)?) => {
        /// The read-model type names a dataset collection may declare.
        pub const ROW_TYPES: &[&str] = &[$(stringify!($ty)),*];

        /// Decode `item` as the read model named `type_name` and discard it: whether
        /// the row is that type. An unknown type name is an error, so a source never
        /// serves a row no read model can show.
        pub fn check_item(type_name: &str, item: &Json, path: &str) -> Result<(), DecodeError> {
            match type_name {
                $(stringify!($ty) => $module::$ty::from_json(item, path).map(|_| ()),)*
                _ => Err(DecodeError {
                    path: path.to_string(),
                    reason: format!("unknown row type {type_name:?}"),
                }),
            }
        }
    };
}

